package com.salespunch360.mobile.ui.account.reports
import android.content.Intent;import java.io.File;import androidx.compose.foundation.clickable;import androidx.compose.foundation.layout.*;import androidx.compose.foundation.lazy.*;import androidx.compose.material.icons.Icons;import androidx.compose.material.icons.filled.*;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.Modifier;import androidx.compose.ui.platform.LocalContext;import androidx.compose.ui.text.font.FontWeight;import androidx.compose.ui.unit.dp;import androidx.core.content.FileProvider;import androidx.lifecycle.compose.collectAsStateWithLifecycle;import androidx.lifecycle.viewmodel.compose.viewModel;import com.salespunch360.mobile.*;import com.salespunch360.mobile.account.*;import com.salespunch360.mobile.ui.account.accounting.Option;import kotlinx.serialization.json.*
@Composable fun AccountReportsScreen(initial:String?,padding:PaddingValues,vm:AccountReportViewModel=viewModel()){val s=vm.state.collectAsStateWithLifecycle().value,context=LocalContext.current;LaunchedEffect(initial){if(initial!=null)vm.choose(initial)};LaunchedEffect(s.export){s.export?.let{e->val f=File(context.cacheDir,e.first);f.writeBytes(e.second);val uri=FileProvider.getUriForFile(context,"${context.packageName}.files",f),mime=when(e.first.substringAfterLast('.')){"pdf"->"application/pdf";"xlsx"->"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";else->"text/csv"};context.startActivity(Intent.createChooser(Intent(Intent.ACTION_SEND).setType(mime).putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION),"Share report"));vm.consumed()}};if(s.report==null){LazyColumn(Modifier.fillMaxSize().padding(padding),contentPadding=PaddingValues(16.dp)){item{Text("Account reports",style=MaterialTheme.typography.headlineSmall)};items(s.options.array("reports")){r->val name=r.jsonPrimitive.content;ListItem(headlineContent={Text(name.replace('-',' ').replaceFirstChar{it.uppercase()})},modifier=Modifier.clickable{vm.choose(name)})}};return};Column(Modifier.fillMaxSize().padding(padding).padding(16.dp)){TextButton({vm.choose(null)}){Text("‹ Reports hub")};Row{OutlinedTextField(s.from,{vm.dates(it,s.to)},label={Text("From")},modifier=Modifier.weight(1f));OutlinedTextField(s.to,{vm.dates(s.from,it)},label={Text("To / as of")},modifier=Modifier.weight(1f))};Row{Option("Branch",s.branchId,s.options.array("branches")){vm.filter("branch",it)};Option("Project",s.projectId,s.options.array("projects")){vm.filter("project",it)}};when(s.report){"general-ledger"->Option("Ledger",s.ledgerId,s.options.array("ledgers")){vm.filter("ledger",it)};"customer-ledger"->Option("Customer",s.customerId,s.options.array("customers")){vm.filter("customer",it)};"vendor-ledger"->Option("Vendor",s.vendorId,s.options.array("vendors")){vm.filter("vendor",it)};"items"->Option("Product",s.productId,s.options.array("products")){vm.filter("product",it)}};Row{Button(vm::run){Text("Run")};listOf("csv","xlsx","pdf").forEach{f->TextButton({vm.export(f)}){Text(f.uppercase())}}};if(s.loading)LinearProgressIndicator(Modifier.fillMaxWidth());s.error?.let{Text(it,color=MaterialTheme.colorScheme.error)};s.data?.let{d->Text(d.str("title"),style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold);LazyRow{item{Column{d.array("columns").forEach{Text(it.jsonPrimitive.content,fontWeight=FontWeight.Bold)}}};items(d.array("rows")){row->Column{row.jsonArray.forEach{Text(it.jsonPrimitive.content)}}};d["totals"]?.jsonArray?.let{t->item{Column{t.forEach{Text(it.jsonPrimitive.content,fontWeight=FontWeight.Bold)}}}}}}}}
